from pptx import Presentation
import os

def inspect_pptx(path):
    prs = Presentation(path)
    for i, slide in enumerate(prs.slides):
        print(f"Slide {i+1}")
        for shape in slide.shapes:
            print(f" - Shape: {shape.name}, Type: {shape.shape_type}")
            if shape.has_text_frame:
                print(f"   Text: {shape.text_frame.text}")
            if shape.shape_type == 7: # GraphicFrame
                if hasattr(shape, "ole_format"):
                    ole = shape.ole_format
                    print(f"   OLE Object: {ole.prog_id}")
                    # Save OLE object to temp file
                    with open(f"ole_{i}_{shape.shape_id}.bin", "wb") as f:
                        f.write(ole.blob)
                    print(f"   Saved OLE blob to ole_{i}_{shape.shape_id}.bin")

if __name__ == "__main__":
    inspect_pptx("input.pptx")

import openpyxl

def read_excel(path):
    wb = openpyxl.load_workbook(path)
    ws = wb.active
    for row in ws.iter_rows(values_only=True):
        print(row)

if __name__ == "__main__":
    read_excel("ole_0_2.bin")

import zipfile
import shutil

def replace_in_zip(zip_path, file_to_replace, new_content_path, output_path):
    with zipfile.ZipFile(zip_path, 'r') as zin:
        with zipfile.ZipFile(output_path, 'w') as zout:
            for item in zin.infolist():
                if item.filename == file_to_replace:
                    with open(new_content_path, 'rb') as f:
                        zout.writestr(item.filename, f.read())
                else:
                    zout.writestr(item, zin.read(item.filename))

if __name__ == "__main__":
    replace_in_zip("input.pptx", "ppt/embeddings/Microsoft_Excel_Worksheet.xlsx", "updated_ole.xlsx", "results.pptx")
